import { useEffect, useReducer } from "react";

function createState(value) {
  return {
    value,
    error: null,
    status: "idle",
  };
}

function reducer(state, action) {
  switch (action.type) {
    case "loading":
      return {
        ...state,
        value: action.initialValue,
        error: null,
        status: "loading",
      };
    case "success":
      return {
        ...state,
        value: action.value,
        error: null,
        status: "success",
      };
    case "error":
      return {
        ...state,
        error: action.error,
        status: "error",
      };
    default:
      return state;
  }
}

export default function useAbortableAsync(
  factory,
  dependencies,
  { initialValue, errorMessage = "Request failed" } = {},
) {
  const [state, dispatch] = useReducer(reducer, initialValue, createState);

  useEffect(() => {
    const controller = new AbortController();

    dispatch({ type: "loading", initialValue });

    let result;

    try {
      result = factory(controller.signal);
    } catch (err) {
      if (err?.name !== "AbortError") {
        dispatch({
          type: "error",
          error: err?.message ?? errorMessage,
        });
      }
      return () => controller.abort();
    }

    Promise.resolve(result)
      .then((nextValue) => {
        if (!controller.signal.aborted) {
          dispatch({ type: "success", value: nextValue });
        }
      })
      .catch((err) => {
        if (err?.name === "AbortError") return;
        dispatch({
          type: "error",
          error: err?.message ?? errorMessage,
        });
      });

    return () => controller.abort();
  }, dependencies);

  return { ...state, loading: state.status === "loading" };
}

